    [('1200 → 3', '3 个传感器各 400 个测量,底层只有 3 个 bucket 文档'), ('1000', '单个 bucket 最多的测量数,3000 个测量拆成 3 个 bucket'), ('2%', '周期性合成数据下时序集合占盘是普通集合的比例(真实数据会高得多)')],
